-- Captured from production 2026-11-12 before Package A (rollback source).
CREATE OR REPLACE FUNCTION public.iapp_sync_examination_core(p_exam jsonb, p_patient_code text DEFAULT NULL::text)
 RETURNS bigint LANGUAGE plpgsql SET search_path TO 'public'
AS $function$ declare v_patient_id bigint; v_legacy_patient_id bigint; v_visit_id bigint; v_exam_id bigint; v_legacy_exam_id text; v_date date; begin if p_exam is null or jsonb_typeof(p_exam) <> 'object' then raise exception 'Invalid examination payload'; end if; v_legacy_patient_id:=nullif((p_exam->>'patientId'),'')::bigint; select id into v_patient_id from public.iapp_patients_core where (v_legacy_patient_id is not null and legacy_id=v_legacy_patient_id) or (p_patient_code is not null and patient_code=p_patient_code) order by case when p_patient_code is not null and patient_code=p_patient_code then 0 else 1 end limit 1; if v_patient_id is null then raise exception 'Core patient not found for examination'; end if; v_legacy_exam_id:=nullif(p_exam->>'id',''); v_date:=nullif(p_exam->>'date','')::date; select id into v_visit_id from public.iapp_visits_core where legacy_id=case when v_legacy_exam_id is not null then 'exam:'||v_legacy_exam_id else null end limit 1; if v_visit_id is null then insert into public.iapp_visits_core(legacy_id,patient_id,doctor_name,visit_date,visit_type,chief_complaint,clinical_summary,notes,status,legacy_patient_id,source_type) values(case when v_legacy_exam_id is not null then 'exam:'||v_legacy_exam_id else null end,v_patient_id,nullif(p_exam->>'doctor',''),v_date,'examination',nullif(p_exam->>'chiefComplaint',''),nullif(p_exam->>'diagnosis',''),nullif(p_exam->>'notes',''),'completed',v_legacy_patient_id,'core_sync') returning id into v_visit_id; else update public.iapp_visits_core set doctor_name=nullif(p_exam->>'doctor',''),visit_date=v_date,visit_type='examination',chief_complaint=nullif(p_exam->>'chiefComplaint',''),clinical_summary=nullif(p_exam->>'diagnosis',''),notes=nullif(p_exam->>'notes',''),status='completed',legacy_patient_id=v_legacy_patient_id,source_type='core_sync' where id=v_visit_id; end if; if v_legacy_exam_id is not null then select id into v_exam_id from public.iapp_examinations_core where legacy_id=v_legacy_exam_id limit 1; end if; if v_exam_id is null then insert into public.iapp_examinations_core(legacy_id,visit_id,examination_date,doctor_name,visual_acuity_od,visual_acuity_os,iop_od,iop_os,anterior_segment,posterior_segment,color_vision,contrast,cover_test,refraction_od,refraction_os,notes,diagnosis_summary,treatment_plan,followup_date) values(v_legacy_exam_id,v_visit_id,v_date,nullif(p_exam->>'doctor',''),nullif(p_exam->>'visualAcuityR',''),nullif(p_exam->>'visualAcuityL',''),nullif(p_exam->>'iopR',''),nullif(p_exam->>'iopL',''),nullif(p_exam->>'anteriorSegment',''),nullif(p_exam->>'posteriorSegment',''),nullif(p_exam->>'colorVision',''),nullif(p_exam->>'contrast',''),nullif(p_exam->>'coverTest',''),'{}'::jsonb,'{}'::jsonb,nullif(p_exam->>'notes',''),nullif(p_exam->>'diagnosis',''),nullif(p_exam->>'treatmentPlan',''),nullif(p_exam->>'followUp','')::date) returning id into v_exam_id; else update public.iapp_examinations_core set visit_id=v_visit_id,examination_date=v_date,doctor_name=nullif(p_exam->>'doctor',''),visual_acuity_od=nullif(p_exam->>'visualAcuityR',''),visual_acuity_os=nullif(p_exam->>'visualAcuityL',''),iop_od=nullif(p_exam->>'iopR',''),iop_os=nullif(p_exam->>'iopL',''),anterior_segment=nullif(p_exam->>'anteriorSegment',''),posterior_segment=nullif(p_exam->>'posteriorSegment',''),color_vision=nullif(p_exam->>'colorVision',''),contrast=nullif(p_exam->>'contrast',''),cover_test=nullif(p_exam->>'coverTest',''),notes=nullif(p_exam->>'notes',''),diagnosis_summary=nullif(p_exam->>'diagnosis',''),treatment_plan=nullif(p_exam->>'treatmentPlan',''),followup_date=nullif(p_exam->>'followUp','')::date where id=v_exam_id; end if; return v_exam_id; end; $function$;
